import React from "react";
import Slider from "react-slick";
import "slick-carousel/slick/slick.css"; // Temel slider stilleri
import "slick-carousel/slick/slick-theme.css"; // Tema stilleri

const EventsSlider = () => {
  const settings = {
    dots: true, // Slider altındaki noktalar
    infinite: true, // Sonsuz kaydırma
    speed: 500, // Kaydırma hızı
    slidesToShow: 1, // Bir seferde gösterilecek slide sayısı
    slidesToScroll: 1, // Her kaydırmada kaç slide kaydırılacak
    arrows: true, // Ok işaretleri
  };

  return (
    <div
    style={{
      position: "relative",
      maxWidth: "1024px",
      height: "400px",
      margin: "30px auto",
      background: "#293349",
      border: "15px solid #00C26D",
      overflow: "hidden",
      borderRadius: "10px",
    }}
  >
  
      {/* Slider İçeriği */}
      <Slider {...settings}>
        <div
          style={{
            height: "100%", // Kapsayıcı boyuta uyumlu
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            color: "#fff", // Yazı rengi
            fontSize: "24px",
            fontWeight: "bold",
            background: "#293349", // Arka plan
          }}
        >
          Slide 1
        </div>
        <div
          style={{
            height: "100%",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            color: "#fff",
            fontSize: "24px",
            fontWeight: "bold",
            background: "#293349",
          }}
        >
          Slide 2
        </div>
        <div
          style={{
            height: "100%",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            color: "#fff",
            fontSize: "24px",
            fontWeight: "bold",
            background: "#293349",
          }}
        >
          Slide 3
        </div>
      </Slider>

      {/* Dekoratif Çizgiler ve Noktalar */}
      <div
        style={{
          position: "absolute",
          top: "10px",
          left: "10px",
          display: "flex",
          flexDirection: "column",
          gap: "10px",
        }}
      >
        {/* Dotlar */}
        {[...Array(3)].map((_, i) => (
          <div
            key={i}
            style={{
              width: "30px",
              height: "10px",
              background: "#00C26D",
            }}
          ></div>
        ))}
      </div>
      <div
        style={{
          position: "absolute",
          top: "10px",
          right: "10px",
        }}
      >
        {/* Kesik Çizgi */}
        <div
          style={{
            width: "150px",
            height: "15px",
            background: "#00C26D",
          }}
        ></div>
      </div>
    </div>
  );
};

export default EventsSlider;
